<script lang="ts" module>
  /**
   * Control glyphs — drawn marks for what a control does to the sound,
   * not what the device is called (user, 2026-10-06: "draw custom images").
   * A tremolo is a wave whose loudness pulses, drive a clipped wave, a comb
   * its notched response, feedback a train of fading echoes. Axis glyphs
   * (rate, depth, tune, tone, …) mark what an XY pad's X and Y move.
   *
   * 32×32, stroked in currentColor so a mark inverts on a slider's fill like
   * its label does. Generated from sampled curves; edit the paths, not the
   * look, by hand.
   */
  export type ControlGlyphName =
    | 'tremolo'
    | 'rate'
    | 'depth'
    | 'drive'
    | 'dirty'
    | 'clean'
    | 'redux'
    | 'blur'
    | 'comb'
    | 'phaser'
    | 'feedback'
    | 'mix'
    | 'output'
    | 'pedal'
    | 'amp'
    | 'wah'
    | 'spring'
    | 'room'
    | 'reverb'
    | 'ringmod'
    | 'pitchhack'
    | 'tune'
    | 'tone';
</script>

